// Separately identified read-only optimization; exact original source precedes it.
#[derive(Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]pub struct JournalPrefix{bytes:u64,sha256:String,sequence:u64,hash:String}
#[derive(Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]pub struct ReadOnlyConfig{original_config_path:PathBuf,journal_prefix:JournalPrefix,mode:String,pub output:PathBuf}
pub(crate)fn source_identity(path:&Path)->Result<String>{identity(path)}
struct ReplayProof{config:Config,bank:V,wallets:Vec<MedianWallet>,publisher:Publication,features:Features,bytes:u64,source_hash:String,identities:V,configuration_hash:String,draining:bool,available:i64,evidence:V}
pub fn read_only_replay(request:&ReadOnlyConfig)->Result<V>{Ok(replay_proof(request)?.evidence)}
fn replay_proof(request:&ReadOnlyConfig)->Result<ReplayProof>{
 need(request.original_config_path.is_absolute()&&["baseline","forward"].contains(&request.mode.as_str())&&request.journal_prefix.bytes>0,"PREFIX_READONLY_CONFIG")?;
 let began=Instant::now();let cfg_bytes=fs::read(&request.original_config_path).map_err(|_|"PREFIX_ORIGINAL_CONFIG_READ")?;let config:Config=serde_json::from_slice(&cfg_bytes).map_err(|_|"PREFIX_ORIGINAL_CONFIG_JSON")?;let bank_raw=fs::read(&config.bank_path).map_err(|_|"PREFIX_BANK_READ")?;need(sha(&bank_raw)==config.bank_file_hash,"PREFIX_ORIGINAL_BANK_CHANGED")?;let bank:V=serde_json::from_slice(&bank_raw).map_err(|_|"PREFIX_BANK_JSON")?;need(digest(&bank)==config.bank_hash&&bank["codeIdentity"]["engineHash"]==env!("MEDIAN_ENGINE_HASH")&&bank["policy"]==fixed_policy()&&bank["featurePolicy"]==feature_policy()&&bank["thresholds"]==json!([1,2,4]),"PREFIX_ORIGINAL_POLICY_CHANGED")?;
 for p in &config.code_pins{need(sha(&fs::read(&p.path).map_err(|_|"PREFIX_ORIGINAL_PIN_READ")?)==p.sha256,"PREFIX_ORIGINAL_PIN_CHANGED")?;}let old_binary=bank["codeIdentity"]["binaryHash"].as_str().ok_or("PREFIX_ORIGINAL_BINARY")?;need(config.code_pins.iter().any(|p|p.sha256==old_binary),"PREFIX_ORIGINAL_BINARY_BINDING")?;
 let original=include_bytes!("frozen_observe.rs");let suffix=b"\ninclude!(\"fast_extension.rs\");\n";need(original.ends_with(suffix)&&config.code_pins.iter().any(|p|p.sha256==sha(&original[..original.len()-suffix.len()]))&&config.code_pins.iter().any(|p|p.sha256==sha(include_bytes!("frozen_kernel.rs"))),"PREFIX_COMPILED_ORIGINAL_SOURCE_PROOF")?;
 let journal_path=config.cohort_dir.join("median-journal.jsonl");need(prefix(&journal_path,request.journal_prefix.bytes)?==request.journal_prefix.sha256,"PREFIX_ORIGINAL_JOURNAL_SHA")?;let mut ledger=Rows::open(&journal_path,0,request.journal_prefix.bytes)?;let mut records=Vec::new();let mut sequence=0u64;let mut previous=String::new();while let Some(row)=ledger.next()?{let mut body=row.clone();body.as_object_mut().ok_or("PREFIX_JOURNAL_BODY")?.shift_remove("hash");sequence+=1;need(row["sequence"]==sequence&&row["previous"]==previous&&row["hash"]==digest(&body),"PREFIX_ORIGINAL_JOURNAL_CHAIN")?;previous=row["hash"].as_str().ok_or("PREFIX_JOURNAL_HASH")?.into();records.push(row);}need(sequence==request.journal_prefix.sequence&&previous==request.journal_prefix.hash&&ledger.offset==request.journal_prefix.bytes,"PREFIX_ORIGINAL_JOURNAL_FRONTIER")?;
 let mut hashes=crate::frontiers::Prefixes::default();hashes.forward=request.mode=="forward";let declare=|hashes:&mut crate::frontiers::Prefixes,path:&Path,info:&V|->Result<()>{hashes.declare(path,info["bytes"].as_u64().ok_or("PREFIX_DECLARATION")?,info["sha256"].as_str().ok_or("PREFIX_DECLARATION")?)};declare(&mut hashes,&config.public_source_path,&bank["publicPrefix"])?;declare(&mut hashes,&config.account_source_path,&bank["accountPrefix"])?;let price_path=config.price_source_path.as_ref().ok_or("PREFIX_PRICE_SOURCE_REQUIRED")?;declare(&mut hashes,price_path,&bank["featurePrefix"])?;
 let mut public_end=bank["publicPrefix"]["bytes"].as_u64().unwrap();let mut account_end=bank["accountPrefix"]["bytes"].as_u64().unwrap();let mut feature_end=bank["featurePrefix"]["bytes"].as_u64().unwrap();for row in &records{let event=&row["event"];if event["kind"]=="source_batch"{let p=row["state"]["sourceBytes"].as_u64().ok_or("PREFIX_PUBLIC_END")?;hashes.declare(&config.public_source_path,p,event["sourcePrefixSha256"].as_str().ok_or("PREFIX_PUBLIC_SHA")?)?;public_end=public_end.max(p);let a=event["accountPrefixBytes"].as_u64().ok_or("PREFIX_ACCOUNT_END")?;hashes.declare(&config.account_source_path,a,event["accountPrefixSha256"].as_str().ok_or("PREFIX_ACCOUNT_SHA")?)?;account_end=account_end.max(a);declare(&mut hashes,price_path,&event["featureFrontier"])?;feature_end=feature_end.max(event["featureFrontier"]["bytes"].as_u64().unwrap());}}
 hashes.seal_forward()?;let cutoff=clock(&bank["cutoff"])?;let initial=bank["publicPrefix"]["bytes"].as_u64().unwrap();need(hashes.hash(&config.public_source_path,initial)?==bank["publicPrefix"]["sha256"],"PREFIX_PUBLIC_CHANGED")?;let mut publisher=Publication::new(&bank["universe"])?;let mut rows=Rows::open(&config.public_source_path,0,initial)?;let mut wallets=[1,2,4].into_iter().map(MedianWallet::new).collect::<Vec<_>>();while let Some(row)=rows.next()?{publisher.apply(&row)?;need(clock(&row["at"])?<=cutoff,"PREFIX_PRIME_FUTURE")?;if row["kind"]=="book"{let q=Quote::parse(&row)?;for w in &mut wallets{w.prime_history(q.clone(),cutoff)?;}}else{let id=if row["kind"]=="invalidation"{row["payload"]["marketId"].as_str()}else{None};for w in &mut wallets{w.boundary(id);}}}need(publisher.sequence()==bank["publicPrefix"]["sequence"]&&publisher.tail_hash()==bank["publicPrefix"]["hash"].as_str().unwrap(),"PREFIX_PUBLIC_BANK_FRONTIER")?;
 // Account chain/schema is the exact archived parser. Prefix SHA is already
 // verified at every declared frame with one forward scan in optimized mode.
 let accounts=Accounts::load(&config,&bank,account_end)?;let account_initial=bank["accountPrefix"]["bytes"].as_u64().unwrap();need(hashes.hash(&config.account_source_path,account_initial)?==bank["accountPrefix"]["sha256"],"PREFIX_ACCOUNT_BANK_CHANGED")?;let seed=Accounts::load(&config,&bank,account_initial)?;let last=seed.rows.last().ok_or("PREFIX_ACCOUNT_BANK_FRONTIER")?;need(last.sequence==bank["accountPrefix"]["sequence"]&&last.hash==bank["accountPrefix"]["hash"]&&last.at<=cutoff,"PREFIX_ACCOUNT_BANK_FRONTIER")?;
 let mut features=Features{path:Some(price_path.clone()),bytes:0,sequence:0,hash:String::new(),sha256:sha(b""),last_at:0,bank:bank.clone()};for w in &mut wallets{w.enable_bulk_history();}let feature_initial=bank["featurePrefix"]["bytes"].as_u64().unwrap();let mut feature_rows=Rows::open(price_path,0,feature_initial)?;while let Some(row)=feature_rows.next()?{need(clock(&row["at"])?<=cutoff,"PREFIX_FEATURE_PRIME_FUTURE")?;features.apply(&row,&mut wallets)?;features.bytes=feature_rows.offset;}features.sha256=hashes.hash(price_path,feature_initial)?;need(features.state()["sequence"]==bank["featurePrefix"]["sequence"]&&features.hash==bank["featurePrefix"]["hash"].as_str().unwrap()&&features.sha256==bank["featurePrefix"]["sha256"],"PREFIX_FEATURE_BANK_FRONTIER")?;let mut feature_future=Rows::open(price_path,feature_initial,feature_end)?;let mut future=Rows::open(&config.public_source_path,initial,public_end)?;
 let configuration_hash=digest(&serde_json::to_value(&config).map_err(|_|"PREFIX_CONFIG_JSON")?);let identities=json!({"public":identity(&config.public_source_path)?,"account":identity(&config.account_source_path)?,"price":Some(identity(price_path)?)});let mut bytes=initial;let mut source_hash=bank["publicPrefix"]["sha256"].as_str().unwrap().to_owned();let mut available=cutoff;let mut draining=!config.entry_enabled||config.entry_drain_path.as_ref().is_some_and(|p|p.exists());let mut exact=0u64;
 for row in &records{let event=&row["event"];draining|=row["state"]["entryDraining"]==true;need(event["configurationHash"]==configuration_hash&&row["state"]["inputIdentities"]==identities,"PREFIX_ORIGINAL_INPUT_IDENTITY")?;match event["kind"].as_str(){Some("genesis")=>need(row["sequence"]==1&&event["bankHash"]==config.bank_hash,"PREFIX_GENESIS")?,Some("operator_entry_drain")=>draining=true,Some("source_batch")=>{let at=clock(&event["availableAt"])?;need(at>=available&&event["sourceStartBytes"]==bytes,"PREFIX_FRAME_CLOCK")?;need(hashes.hash(&config.account_source_path,event["accountPrefixBytes"].as_u64().unwrap())?==event["accountPrefixSha256"],"PREFIX_ACCOUNT_FRAME_CHANGED")?;
 need(hashes.hash(price_path,features.bytes)?==features.sha256,"PREFIX_FEATURE_FRAME_CHANGED")?;let end=event["featureFrontier"]["bytes"].as_u64().unwrap();while feature_future.offset<end{let row=feature_future.next()?.ok_or("PREFIX_FEATURE_TRUNCATED")?;need(feature_future.offset<=end&&clock(&row["at"])?<=at,"PREFIX_FEATURE_FRAME_CAUSALITY")?;features.apply(&row,&mut wallets)?;features.bytes=feature_future.offset;}features.sha256=hashes.hash(price_path,features.bytes)?;need(features.state()==event["featureFrontier"],"PREFIX_FEATURE_STATE_CHANGED")?;
 for observed in event["observations"].as_array().ok_or("PREFIX_OBSERVATIONS")?{let actual=future.next()?.ok_or("PREFIX_PUBLIC_TRUNCATED")?;need(actual["sequence"]==observed["sequence"]&&actual["hash"]==observed["hash"],"PREFIX_ORIGINAL_PUBLIC_CHANGED")?;apply(&mut wallets,&mut publisher,&actual,at,cutoff,&accounts,event["allowNewEntries"]==true,Some(&observed["accountEvidence"]))?;}bytes=future.offset;source_hash=event["sourcePrefixSha256"].as_str().unwrap().into();available=at;draining|=event["allowNewEntries"]!=true;},_=>return Err("PREFIX_ORIGINAL_EVENT_KIND".into())}
 need(row["state"]["caseStateHashes"]==self::hashes(&wallets)?&&row["state"]["sourceBytes"]==bytes&&row["state"]["sourceSequence"]==publisher.sequence()&&row["state"]["sourceHash"]==publisher.tail_hash()&&row["state"]["featureFrontier"]==features.state(),"PREFIX_EXACT_ORIGINAL_FINANCIAL_CHECKPOINT")?;exact+=1;}
 need(hashes.hash(&config.public_source_path,bytes)?==source_hash,"PREFIX_FINAL_PUBLIC_CHANGED")?;
 let states=wallets.iter().map(MedianWallet::checkpoint).collect::<Result<Vec<_>>>()?;let evidence=json!({"schemaVersion":1,"mode":request.mode,"utilityEngineHash":env!("FAST_REPLAY_ENGINE_HASH"),"originalEngineHash":env!("MEDIAN_ENGINE_HASH"),"bankHash":config.bank_hash,"originalConfigSha256":sha(&cfg_bytes),"sealedJournal":{"bytes":request.journal_prefix.bytes,"sha256":request.journal_prefix.sha256,"sequence":sequence,"hash":previous},"exactOriginalCheckpointsVerified":exact,"stateHashes":self::hashes(&wallets)?,"states":states,"reports":wallets.iter().map(|w|w.report(available)).collect::<Vec<_>>(),"source":{"bytes":bytes,"sha256":source_hash,"sequence":publisher.sequence(),"hash":publisher.tail_hash()},"feature":features.state(),"accountBytes":account_end,"lastAvailableAtMs":available,"entryDraining":draining,"inputIdentities":identities,"prefixCalls":hashes.calls,"prefixBytesRead":hashes.bytes_read,"distinctFrontiers":hashes.declarations.values().map(std::collections::BTreeMap::len).sum::<usize>(),"elapsedMs":began.elapsed().as_secs_f64()*1000.,"originalFilesModified":false,"networkRequests":0,"competitionOrders":0,"profitabilityEstablished":false});Ok(ReplayProof{config,bank,wallets,publisher,features,bytes,source_hash,identities,configuration_hash,draining,available,evidence})
}
#[derive(Clone,Serialize,Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]pub struct ContinuationConfig{pub original_config_path:PathBuf,pub new_binary_path:PathBuf,pub new_binary_hash:String,pub new_source_pins:Vec<SourcePin>,#[serde(default="one_second")]pub interval_ms:u64}
fn one_second()->u64{1000}
fn continuation_pins(config:&ContinuationConfig)->Result<()> {need(config.original_config_path.is_absolute()&&config.new_binary_path.is_absolute()&&hex(&config.new_binary_hash)&&config.new_source_pins.len()>=9&&config.new_source_pins.len()<=100&&(200..=10000).contains(&config.interval_ms),"CONTINUATION_CONFIGURATION")?;let exe=std::env::current_exe().map_err(|_|"CONTINUATION_CURRENT_BINARY")?;need(fs::canonicalize(&exe).map_err(|_|"CONTINUATION_BINARY")?==fs::canonicalize(&config.new_binary_path).map_err(|_|"CONTINUATION_BINARY")?&&sha(&fs::read(&exe).map_err(|_|"CONTINUATION_BINARY")?)==config.new_binary_hash&&config.new_source_pins.iter().any(|p|p.path==config.new_binary_path&&p.sha256==config.new_binary_hash),"CONTINUATION_NEW_BINARY_PIN")?;for p in &config.new_source_pins{need(p.path.is_absolute()&&hex(&p.sha256)&&sha(&fs::read(&p.path).map_err(|_|"CONTINUATION_SOURCE_PIN")?)==p.sha256,"CONTINUATION_SOURCE_PIN_CHANGED")?;}Ok(())}
pub fn run_continuation(config:ContinuationConfig,seconds:u64,maximum_batches:u64,maximum_rows:usize)->Result<V>{
 need((1..=3600).contains(&seconds)&&(1..=10000).contains(&maximum_batches)&&(1..=4096).contains(&maximum_rows),"CONTINUATION_EXPLICIT_BOUNDS")?;continuation_pins(&config)?;let original_raw=fs::read(&config.original_config_path).map_err(|_|"CONTINUATION_ORIGINAL_CONFIG")?;let old:Config=serde_json::from_slice(&original_raw).map_err(|_|"CONTINUATION_ORIGINAL_CONFIG")?;let mut stops=old.stop_paths.clone();stops.push(old.cohort_dir.join("STOP"));need(!stops.iter().any(|p|p.exists()),"CONTINUATION_STOPPED")?;let owner=OwnerLock::acquire(&old.cohort_dir.join("median.lock"))?;
 let journal_path=old.cohort_dir.join("median-journal.jsonl");let end=complete(&journal_path)?;need(end==fs::metadata(&journal_path).map_err(|_|"CONTINUATION_ORIGINAL_JOURNAL")?.len(),"CONTINUATION_PARTIAL_ORIGINAL_JOURNAL")?;let mut source=Rows::open(&journal_path,0,end)?;let mut last=V::Null;while let Some(row)=source.next()?{last=row;}let binding=JournalPrefix{bytes:end,sha256:prefix(&journal_path,end)?,sequence:last["sequence"].as_u64().ok_or("CONTINUATION_ORIGINAL_HEAD")?,hash:last["hash"].as_str().ok_or("CONTINUATION_ORIGINAL_HEAD")?.into()};
 let proof=replay_proof(&ReadOnlyConfig{original_config_path:config.original_config_path.clone(),journal_prefix:binding,mode:"forward".into(),output:PathBuf::new()})?;let imported=proof.evidence.clone();let new_identity=json!({"binaryHash":config.new_binary_hash,"engineHash":env!("FAST_REPLAY_ENGINE_HASH"),"sourcePins":config.new_source_pins,"sourcePinsHash":digest(&serde_json::to_value(&config.new_source_pins).map_err(|_|"CONTINUATION_PIN_JSON")?)});let original_lineage=json!({"bankHash":proof.config.bank_hash,"bankFileHash":proof.config.bank_file_hash,"configurationHash":proof.configuration_hash,"configFileSha256":sha(&original_raw),"codePins":proof.config.code_pins,"originalBinaryHash":proof.bank["codeIdentity"]["binaryHash"],"originalEngineHash":proof.bank["codeIdentity"]["engineHash"]});
 let revision_path=old.cohort_dir.join("median-code-revisions.jsonl");let mut revisions=OwnedJournal::open(&revision_path,owner.token(),&stops)?;let mut previous_identity=V::Null;if revisions.status()["sequence"].as_u64().unwrap_or(0)>0{journal_rows(&revision_path,|row|{need(row["event"]["originalLineage"]==original_lineage&&["median_observer_code_revision","bounded_session_start","bounded_session_end"].contains(&row["event"]["kind"].as_str().unwrap_or("")),"CONTINUATION_REVISION_LINEAGE")?;previous_identity=row["event"]["newIdentity"].clone();Ok(())})?;}
 let now=millis();let at=iso(now)?;let kind=if previous_identity==new_identity{"bounded_session_start"}else{"median_observer_code_revision"};revisions.commit(json!({"importProof":imported,"originalStateHashes":hashes(&proof.wallets)?}),json!({"kind":kind,"originalLineage":original_lineage,"newIdentity":new_identity,"recordedAt":at,"originalFinancialJournalUnchangedAtBoundary":true,"accountingReset":false,"networkRequests":0,"competitionOrders":0,"executionAuthority":false}),&at)?;
 let revision=json!({"journal":"median-code-revisions.jsonl","sequence":revisions.status()["sequence"],"hash":revisions.status()["tailHash"],"newBinaryHash":config.new_binary_hash,"newEngineHash":env!("FAST_REPLAY_ENGINE_HASH"),"originalBankHash":proof.config.bank_hash,"originalBinaryHash":proof.bank["codeIdentity"]["binaryHash"],"accountingReset":false});
 let journal=OwnedJournal::open(&journal_path,owner.token(),&stops)?;need(journal.status()["sourceBytes"]==imported["sealedJournal"]["bytes"]&&journal.status()["sourceHash"]==imported["sealedJournal"]["sha256"]&&journal.status()["sequence"]==imported["sealedJournal"]["sequence"]&&journal.status()["tailHash"]==imported["sealedJournal"]["hash"],"CONTINUATION_ORIGINAL_HEAD_CHANGED")?;
 // Attach the exact original in-process core only after independent source,
 // wallet, old-artifact and new-code provenance verification. No bank rebind.
 let mut actor=Observer{config:proof.config,bank:proof.bank,wallets:proof.wallets,publisher:proof.publisher,journal,source_bytes:proof.bytes,source_hash:proof.source_hash,identities:proof.identities,configuration_hash:proof.configuration_hash,features:proof.features,draining:proof.draining,failed:false,last_available:proof.available,owner};actor.guard()?;
 let started=Instant::now();let mut batches=0u64;while started.elapsed()<Duration::from_secs(seconds)&&batches<maximum_batches{continuation_pins(&config)?;need(sha(&fs::read(&config.original_config_path).map_err(|_|"CONTINUATION_ORIGINAL_CONFIG")?)==sha(&original_raw),"CONTINUATION_ORIGINAL_CONFIG_CHANGED")?;actor.consume(millis(),maximum_rows)?;batches+=1;let mut report=actor.report(millis());report["observer"]["codeRevision"]=revision.clone();report["observer"]["coldImports"]=json!(1);report["observer"]["sessionBatches"]=json!(batches);atomic_json(&actor.config.cohort_dir.join("stats.json"),&report)?;thread::sleep(Duration::from_millis(config.interval_ms).min(Duration::from_secs(seconds).saturating_sub(started.elapsed())));}
 let at=iso(millis())?;let report=actor.report(millis());revisions.commit(json!({"caseStateHashes":hashes(&actor.wallets)?,"financialCases":report["cases"],"sourceSequence":actor.publisher.sequence(),"sourceHash":actor.publisher.tail_hash(),"featureFrontier":actor.features.state()}),json!({"kind":"bounded_session_end","originalLineage":original_lineage,"newIdentity":new_identity,"completedAt":at,"batches":batches,"accountingReset":false,"networkRequests":0,"competitionOrders":0,"executionAuthority":false}),&at)?;
 Ok(json!({"mode":"bounded_native_median_code_continuation_v1","completed":true,"batches":batches,"coldImports":1,"codeRevision":revision,"cases":report["cases"],"sourceSequence":actor.publisher.sequence(),"journalSequence":actor.journal.status()["sequence"],"originalConfigUnchanged":true,"originalBankUnchanged":true,"accountingReset":false,"networkRequests":0,"competitionOrders":0,"executionAuthority":false,"profitabilityEstablished":false}))
}
